const body = $input.first().json.body ?? $input.first().json;
const staticData = $getWorkflowStaticData('global');
staticData.streaks = staticData.streaks || {};

const alerts = [];
for (const r of (body.results || [])) {
  const key = r.url;
  const isBroken = r.outcome === 'broken';
  const prev = staticData.streaks[key] || 0;
  const streak = isBroken ? prev + 1 : 0;
  staticData.streaks[key] = streak;
  if (streak >= 3) {
    alerts.push({ url: r.url, reason: r.reason, streak, references: r.references });
  }
}

return [{ json: { alerts, summary: body.summary } }];
